 static readonly List<Flight> flights=new();static readonly AirdropLedger ledger=new();static bool infoPage=true;static float nextInformation;static Vector2 infoScroll;static string information="进入战局后显示投放计划。";static readonly HashSet<string> fastBefore=new();static bool fastPending;static float fastUntil;
