 static void InitializeInformation(Plugin plugin){try{plugin.Patches.Patch(AccessTools.Method(typeof(ServerPlane),"Init"),postfix:new HarmonyMethod(typeof(AirdropControl),nameof(FlightStarted)));plugin.Patches.Patch(AccessTools.Method(typeof(ServerPlane),"AirdropReached"),postfix:new HarmonyMethod(typeof(AirdropControl),nameof(Released)));plugin.Log.LogInfo("Airdrop information ready: native flight/drop events and next-attempt timer");}catch(Exception e){plugin.Log.LogError("Airdrop information hooks: "+e);}}
