 static void TickInformation(GameWorld current){if(fastPending){if(Time.unscaledTime>fastUntil){fastPending=false;notice="立即投放等待超时，请检查空投是否已生成。";}else{var flight=flights.FirstOrDefault(f=>!fastBefore.Contains(f.Key)&&Flying(f)&&f.Plane._airdrop!=null);if(flight!=null){fastPending=false;Action(()=>DropNow(flight));}}}if(!InterfaceMenu.AirdropPage||Time.unscaledTime<nextInformation)return;nextInformation=Time.unscaledTime+.5f;
