  information=next+"\n自然投放已触发 "+count.ToString("0")+"／"+max.ToString("0")+" · 每次概率 "+(manager.PlaneAirdropChance*100).ToString("0.#")+"%";if(remaining.HasValue&&Elapsed is double raidElapsed&&count<max&&elapsed<=manager.PlaneAirdropEnd)information+=" · 预计战局进行至 "+RaidRules.Clock(raidElapsed+remaining.Value);if(manager._projectileSuccessPositions?.Count>0&&AirdropLedger.Remaining(manager._nextAirdropTimeByFlare,elapsed) is double flare)information+="\n信号弹待投 "+manager._projectileSuccessPositions.Count+" 处 · "+RaidRules.Clock(flare)+" 后尝试";
 }
 static void Immediate(){EnsureInformation();if(!RaidClock.Active)throw new ArgumentException("请进入战局后投放。");fastBefore.Clear();foreach(var flight in flights)fastBefore.Add(flight.Key);Summon();fastPending=true;fastUntil=Time.unscaledTime+45;notice="已请求立即投放：物资准备好后跳过飞机进场，箱体仍会正常降落。";}
